class Solution {
  public int longestPalindromicSubsequence(String s, int k) {
    int n = s.length();
    int[][] next = new int[n][k + 1], cur = new int[n][k + 1];
    for (int i = n - 1; i >= 0; i--) {
      for (int j = i; j < n; j++) {
        for (int t = 0; t <= k; t++) {
          if (i == j) {
            cur[j][t] = 1;
            continue;
          }
          int best = Math.max(next[j][t], cur[j - 1][t]);
          int diff = Math.abs(s.charAt(i) - s.charAt(j));
          int cost = Math.min(diff, 26 - diff);
          if (cost <= t) {
            int inner = i + 1 <= j - 1 ? next[j - 1][t - cost] : 0;
            best = Math.max(best, 2 + inner);
          }
          cur[j][t] = best;
        }
      }
      int[][] tmp = next;
      next = cur;
      cur = tmp;
    }
    return next[n - 1][k];
  }
}
